import React from 'react';
import { graphql, useStaticQuery } from 'gatsby';
import Layout from '../components/Layout';

export default function AboutPage() {
  const data = useStaticQuery(graphql`
    query AboutPageQuery {
      site { siteMetadata {
        author { name bio avatar }
        social { platform url }
      }}
    }
  `);
  const { author, social } = data.site.siteMetadata;

  return (
    <Layout active="about">
      <div style={{ maxWidth: 680, margin: '0 auto', padding: '80px 0 120px' }}>
        <div style={{ display: 'flex', gap: 24, alignItems: 'center', marginBottom: 40 }}>
          <img
            src={author.avatar}
            alt={author.name}
            style={{ width: 88, height: 88, borderRadius: '50%', objectFit: 'cover', flexShrink: 0 }}
          />
          <div>
            <h1 style={{ fontFamily: 'var(--font-serif)', fontWeight: 400, fontSize: 32, margin: '0 0 6px' }}>
              {author.name}
            </h1>
            <p style={{ margin: 0, color: 'var(--muted)', fontSize: 14 }}>
              Software Craftsman. Exploring the world of AI and Machine Learning. Always learning.
            </p>
          </div>
        </div>

        <p style={{ lineHeight: 1.8, marginBottom: 20 }}>
          A passionate full stack software engineer having 11+ years of experience in building scalable enterprise systems.
          I have worked predominantly with the JVM and Javascript ecosystem but currently working on Golang.
          For me, software engineering is all about solving problems in the most optimal way. I am an avid practitioner
          of clean code practices and love to read about System Design and Architectures. When I am not coding I love to
          explore AI tools, writing blogs, I love to play playstation, read anything about aviation or go out for a long
          drive and of-course I am foodie by heart.
        </p>

        <p style={{ lineHeight: 1.8, marginBottom: 20 }}>
          I'm naturally curious, always asking questions, whether it's a teammate or even the CEO. I believe in full
          transparency at work: no office politics, no hidden agendas. Concerns should be raised directly, and
          communication should be clear, honest, and to the point. I'm a big fan of the "no hellos, just messages"
          approach in chats.
        </p>

        <p style={{ lineHeight: 1.8, marginBottom: 20 }}>
          I value processes, but only as much as they help productivity, not as rigid rules that slow us down.
          My goal is simple: get things built. Clients and colleagues trust me to deliver, and I work best in
          environments where that trust is mutual. I don't need micromanagement, and I don't micromanage others.
        </p>

        <p style={{ lineHeight: 1.8, marginBottom: 40 }}>
          I'm not a "resource." I'm an engineer, and I thrive in employee-driven environments where trust, freedom,
          and respect come first. I don't care about fancy perks or superficial gestures. I care about being trusted
          and having the space to do my best work. That's how I work, and that's how I thrive.
        </p>

        <h2 style={{ fontFamily: 'var(--font-serif)', fontWeight: 400, fontSize: 22, margin: '0 0 16px' }}>
          Get in touch
        </h2>
        <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
          {social.map(s => (
            <a
              key={s.platform}
              href={s.url}
              rel="me noopener noreferrer"
              style={{
                fontFamily: 'var(--font-mono)',
                fontSize: 13,
                color: 'var(--ink)',
                background: 'var(--surface)',
                border: '1px solid var(--border)',
                borderRadius: 4,
                padding: '6px 14px',
                textDecoration: 'none',
              }}
            >
              {s.platform}
            </a>
          ))}
        </div>
      </div>
    </Layout>
  );
}
